const defaults = {mode:'sample',brand:{...sampleBrand},tasks:{},savedIdeas:[],library:[],calendar:[],notifications:true,consent:false};
function loadProduct(){try{const stored=JSON.parse(localStorage.getItem('brandyar-product-v1'));if(stored&&typeof stored==='object')return {...defaults,...stored,brand:{...defaults.brand,...stored.brand},tasks:stored.tasks||{},savedIdeas:Array.isArray(stored.savedIdeas)?stored.savedIdeas:[],library:Array.isArray(stored.library)?stored.library:[],calendar:Array.isArray(stored.calendar)?stored.calendar:[]}}catch{}return {...defaults,brand:{...sampleBrand},tasks:{},savedIdeas:[],library:[],calendar:[]}}
let product=loadProduct();
function persist(){if(product.consent)localStorage.setItem('brandyar-product-v1',JSON.stringify(product))}
function esc(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function notify(message){let area=document.getElementById('toast');if(!area)return;area.textContent=message;area.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>area.hidden=true,4000)}
function link(path,label,cls='btn btn-dark'){return `<a class="${cls}" href="${path==='app'?'#/app':`#/app/${path}`}">${label} ${icon('arrow')}</a>`}
function emptyPanel(title,text,path,label){return `<div class="panel empty-state">${icon('idea')}<h3>${title}</h3><p>${text}</p>${link(path,label)}</div>`}
function appTitle(title,sub,actions=''){return `<div class="app-heading app-heading-row"><div><h1>${title}</h1><p>${sub}</p></div><div class="toolbar-actions">${actions}</div></div>`}
function brandReady(){return product.mode==='sample'||Boolean(product.brand.name&&product.brand.field&&product.brand.audience)}
function currentTask(){for(let i=0;i<taskGroups.length;i++)for(let j=0;j<taskGroups[i].tasks.length;j++)if(product.tasks[`${i}-${j}`]!=='done')return {i,j,task:taskGroups[i].tasks[j]};return null}
function taskStatus(i,j){return product.tasks[`${i}-${j}`]||'todo'}
function taskRow(i,j){const [title,time,path]=taskGroups[i].tasks[j],status=taskStatus(i,j);return `<div class="work-item"><div><strong>${title}</strong><small>${time} · ${taskGroups[i].title}</small></div><label class="sr-only" for="task-${i}-${j}">وضعیت ${title}</label><select id="task-${i}-${j}" data-task="${i}-${j}"><option value="todo" ${status==='todo'?'selected':''}>انجام‌نشده</option><option value="doing" ${status==='doing'?'selected':''}>در حال انجام</option><option value="review" ${status==='review'?'selected':''}>نیازمند بازبینی</option><option value="done" ${status==='done'?'selected':''}>انجام‌شده</option></select><a href="#/app/${path}${path==='settings'?'?section=brand':''}" class="inline-link">شروع اقدام ${icon('arrow')}</a></div>`}
function ideaCard(item,index){const saved=product.savedIdeas.includes(index);return `<article class="panel idea-detail"><div class="card-meta"><span class="tag">${item.goal}</span><span>${item.format} · ${item.type}</span><span>مرحله ${item.stage}</span></div><h3>${item.title}</h3><p>${item.why}</p><div class="card-meta"><span>سختی: ${item.effort}</span><span>زمان: ${item.time} دقیقه</span><span>موضوع: ${item.topic}</span></div><div class="card-actions"><a href="#/app/studio?idea=${index}" class="btn btn-dark btn-sm">ساخت سناریو</a><button type="button" class="btn btn-outline btn-sm" data-action="plan-idea" data-id="${index}">افزودن به برنامه هفته</button><button type="button" class="btn btn-outline btn-sm" data-action="save-idea-v2" data-id="${index}" ${saved?'disabled':''}>${saved?'ذخیره شد':'ذخیره'}</button></div></article>`}
appPages.app=()=>{const nextIndex=taskGroups[1].tasks.findIndex((_,j)=>taskStatus(1,j)!=='done'),next=nextIndex>=0?{i:1,j:nextIndex,task:taskGroups[1].tasks[nextIndex]}:currentTask(),complete=Object.values(product.tasks).filter(v=>v==='done').length;if(!brandReady())return `${appTitle('به برندیار خوش آمدید','برای دیدن پیشنهادهای متناسب با برندتان، ابتدا اطلاعات اصلی را کامل کنید.')}${emptyPanel('برای شروع، برندتان را معرفی کنید','می‌توانید بدون اتصال اینستاگرام حوزه تخصص، مخاطب و نمونه محتوای خود را ثبت کنید.','onboarding','تکمیل پروفایل برند')}<div class="app-grid">${emptyPanel('هنوز تحلیلی ندارید','پس از تکمیل پروفایل، امکان مشاهده نمونه مسیر تحلیل فراهم می‌شود.','onboarding','شروع کنید')}${emptyPanel('اینستاگرام متصل نیست','برای شروع به اتصال پیج نیازی نیست.','connection','روش‌های شروع')}</div>`;return `${appTitle('برندت را آگاهانه رشد بده.','مرور اقدام‌های هفته برای '+esc(product.brand.name)+'.',link('roadmap','شروع اقدام بعدی')+link('studio','ساخت سناریوی جدید','btn btn-outline'))}<div class="demo-switch"><button type="button" class="inline-link" data-action="fresh-start">دیدن تجربه کاربر جدید بدون داده</button></div><div class="app-banner"><div><span class="eyebrow">اولویت این هفته</span><h2>اعتمادسازی با روایت تجربه‌های واقعی</h2><p>روی اقدامی تمرکز کن که به شفافیت و اعتبار برندت کمک می‌کند.</p></div>${link(next?next.task[2]:'roadmap',next?'شروع اقدام بعدی':'دیدن مسیر رشد','btn btn-light')}</div><div class="metric-grid operational-metrics"><article class="metric-card"><span class="label">امتیاز برند · نمونه</span><strong>70 / 100</strong><small>تغییر نسبت به تحلیل قبل: +5</small></article><article class="metric-card"><span class="label">مرحله فعلی</span><strong>2 / 4</strong><small>ساخت اعتبار و اعتماد</small></article><article class="metric-card"><span class="label">اقدام‌های انجام‌شده</span><strong>${complete} / 10</strong><small>بر اساس چک‌لیست شما</small></article><article class="metric-card"><span class="label">اتصال اینستاگرام</span><strong class="metric-text">متصل نیست</strong><small>آخرین همگام‌سازی: انجام نشده</small></article></div><div class="app-grid"><article class="panel"><h2>6 بُعد سلامت برند</h2><p>امتیازهای نمونه برای نمایش تجربه محصول، نه تحلیل پیج واقعی</p><div class="mini-score-grid">${scoreDetails.map(d=>`<div><span>${d.title}</span><strong>${d.score} / 100</strong></div>`).join('')}</div>${link('analysis','جزئیات تحلیل','dashboard-link')}</article><article class="panel"><h2>3 اقدام مهم هفته</h2><p>وضعیت اقدام‌ها را خودتان مشخص کنید</p>${taskRow(0,0)}${taskRow(1,0)}${taskRow(1,1)}</article></div><div class="app-grid"><article class="panel"><h2>3 ایده متناسب با مسیر برند</h2><p>ایده‌های نمونه برای مدرس‌های آموزشی؛ از اطلاعات واردشده شما تولید نشده‌اند</p>${sampleIdeas.slice(0,3).map((v,i)=>`<div class="work-item"><strong>${v.title}</strong><a class="inline-link" href="#/app/studio?idea=${i}">ساخت سناریو ${icon('arrow')}</a></div>`).join('')}${link('ideas','همه ایده‌ها','dashboard-link')}</article><article class="panel"><h2>مرحله فعلی نقشه راه</h2><p>ساخت اعتبار و اعتماد · مرحله 2 از 4</p><div class="progress-track"><i style="width:${Math.round(taskGroups[1].tasks.filter((_,j)=>taskStatus(1,j)==='done').length/3*100)}%"></i></div><p>اقدام بعدی: ${esc(next?.task[0]||'بازبینی مسیر رشد')}</p>${link('roadmap','مشاهده نقشه راه','dashboard-link')}<hr><h2>وضعیت اتصال</h2><p>اینستاگرام متصل نیست · آخرین همگام‌سازی: انجام نشده</p>${link('connection','راهنمای اتصال امن','dashboard-link')}</article></div>`};
appPages.analysis=()=>!brandReady()?`${appTitle('تحلیل برند','برای دیدن این بخش ابتدا پروفایل برند را تکمیل کنید.')}${emptyPanel('داده‌ای برای تحلیل نیست','از ورود دستی اطلاعات برند شروع کنید.','onboarding','تکمیل پروفایل')}`:`${appTitle('تحلیل برند','نمونه تحلیل برای نشان‌دادن منطق تصمیم‌گیری محصول.',link('roadmap','رفتن به نقشه راه'))}<div class="notice">امتیازها و دلیل‌های زیر داده نمایشی هستند و از اینستاگرام یا هوش مصنوعی استخراج نشده‌اند.</div><div class="app-grid"><article class="panel"><h2>امتیاز کلی برند</h2><p>تغییر نسبت به تحلیل نمونه قبلی: +5 امتیاز</p><div class="score-panel-body"><div class="score-ring"><span>70<small>از 100</small></span></div><div class="bar-list">${scoreDetails.map(d=>`<div class="bar-item"><span>${d.title}</span><strong>${d.score}</strong><div class="track"><i style="width:${d.score}%"></i></div></div>`).join('')}</div></div></article><article class="panel"><h2>اولویت پیشنهادی</h2><p>اعتمادسازی و مسیر تبدیل، هر دو فرصت بهبود دارند.</p><div class="notice">${scoreDetails[2].reason} ${scoreDetails[2].action}</div>${link('studio','ساخت سناریوی تجربه شخصی')}</article></div><div class="analysis-grid">${scoreDetails.map(d=>`<article class="panel analysis-card"><div class="analysis-head"><h2>${d.title}</h2><strong>${d.score} / 100</strong></div><span class="tag ${d.score<65?'warn':d.score<75?'attention':''}">${d.score<65?'اولویت بالا':d.score<75?'نیازمند توجه':'خوب'}</span><p><strong>دلیل تحلیل:</strong> ${d.reason}</p><p><strong>اثر احتمالی:</strong> ${d.effect}</p><p><strong>اقدام پیشنهادی:</strong> ${d.action}</p>${link(d.path,'شروع اقدام','btn btn-outline btn-sm')}</article>`).join('')}</div>`;
appPages.roadmap=()=>`${appTitle('نقشه راه رشد','مسیر 4 مرحله‌ای برای تبدیل شناخت به اقدام.',link('calendar','برنامه هفته','btn btn-outline'))}<div class="notice">این هفته روی روایت یک تجربه معتبر و شفاف‌سازی پیام برند تمرکز کنید. زمان‌ها تقریبی هستند.</div><div class="roadmap-grid">${taskGroups.map((group,i)=>{const count=group.tasks.filter((_,j)=>taskStatus(i,j)==='done').length,pct=Math.round(count/group.tasks.length*100);return `<section class="panel roadmap-stage"><div class="analysis-head"><div><span class="tag">مرحله ${i+1}${i===1?' · مرحله فعال':''}</span><h2>${group.title}</h2></div><strong>${pct}%</strong></div><div class="progress-track"><i style="width:${pct}%"></i></div><p>اقدام بعدی: ${group.tasks.find((_,j)=>taskStatus(i,j)!=='done')?.[0]||'بازبینی و ادامه مسیر'}</p>${group.tasks.map((_,j)=>taskRow(i,j)).join('')}</section>`}).join('')}</div>`;
let ideaFilters={goal:'',format:'',time:'',stage:'',topic:''};
const options=(values,selected,label)=>`<option value="">${label}</option>${values.map(v=>`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(v)}</option>`).join('')}`;
appPages.ideas=()=>{const filtered=sampleIdeas.map((idea,i)=>({...idea,index:i})).filter(v=>(!ideaFilters.goal||v.goal===ideaFilters.goal)&&(!ideaFilters.format||v.format===ideaFilters.format)&&(!ideaFilters.time||(ideaFilters.time==='short'?v.time<=25:v.time>25))&&(!ideaFilters.stage||String(v.stage)===ideaFilters.stage)&&(!ideaFilters.topic||v.topic===ideaFilters.topic));return `${appTitle('ایده‌های محتوا','ایده‌های نمونه متناسب با مسیر مدرس‌های آموزشی.',link('studio','ساخت سناریوی جدید'))}<div class="panel quick-goal"><h2>ایده متناسب با هدف امروزت می‌خواهی؟</h2><div class="chip-row">${[['افزایش اعتماد','اعتماد'],['معرفی محصول','فروش'],['جذب مخاطب جدید','آگاهی'],['تعامل بیشتر','تعامل'],['فروش مشاوره یا دوره','فروش']].map(([label,goal])=>`<button class="chip" type="button" data-quick-goal="${goal}">${label}</button>`).join('')}</div></div><div class="filter-row">${[['goal','هدف محتوا',['آگاهی','تعامل','اعتماد','اعتبار','فروش']],['format','فرمت',['ریلز','پست اسلایدی','استوری','لایو']],['time','زمان تولید',['short','long']],['stage','مرحله رشد',['1','2','3','4']],['topic','موضوع',['فروش دوره','داستان برند','ساخت دوره','شناخت مخاطب']]].map(([key,label,values])=>`<label>${label}<select data-filter="${key}">${key==='time'?`<option value="">همه</option><option value="short" ${ideaFilters.time==='short'?'selected':''}>تا 25 دقیقه</option><option value="long" ${ideaFilters.time==='long'?'selected':''}>بیش از 25 دقیقه</option>`:options(values,ideaFilters[key],'همه')}</select></label>`).join('')}<button type="button" class="btn btn-outline btn-sm" data-action="clear-filters">پاک‌کردن فیلترها</button></div><p class="results-count">${filtered.length} ایده پیدا شد · داده‌های نمایشی</p><div class="ideas-list">${filtered.length?filtered.map(v=>ideaCard(v,v.index)).join(''):emptyPanel('ایده‌ای با این فیلترها پیدا نشد','فیلترها را تغییر دهید یا پاک کنید.','ideas','همه ایده‌ها')}</div>`};
let studioTab='have',studioDraft=null,activeStudioKey='';
const selectField=(id,label,values)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${values.map(v=>`<option>${v}</option>`).join('')}</select></div>`;
appPages.studio=()=>{const id=new URLSearchParams(location.hash.split('?')[1]||'').get('idea'),selected=id!==null?sampleIdeas[Number(id)]:undefined,editId=new URLSearchParams(location.hash.split('?')[1]||'').get('edit'),editItem=product.library.find(v=>v.id===editId);if(editItem?.draft&&(!studioDraft||studioDraft.topic!==editItem.title)){studioDraft=editItem.draft;studioTab=editItem.draft.mode}else if(editItem&&!editItem.draft)studioTab='have';return `${appTitle('استودیوی سناریو','سناریویی بساز که به جایگاه، اعتماد یا فروش برندت خدمت کند.',link('library','کتابخانه','btn btn-outline'))}<div class="notice">این ابزار در نسخه نمایشی، پیش‌نویس ساختاری می‌سازد؛ خروجی هوش مصنوعی یا تضمین نتیجه نیست. پیام اصلی شما در بازنویسی حفظ می‌شود.</div><div class="tabs" role="tablist" aria-label="روش ساخت سناریو"><button type="button" role="tab" aria-selected="${studioTab==='have'}" data-tab="have">سناریو دارم</button><button type="button" role="tab" aria-selected="${studioTab==='new'}" data-tab="new">سناریو ندارم</button></div><div class="app-grid studio-layout"><section class="panel"><h2>${studioTab==='have'?'بازنویسی سناریوی موجود':'ساخت سناریو از صفر'}</h2><p>فیلدهای لازم را کامل کنید و پیش‌نویس قابل ویرایش بگیرید.</p><form id="studio-form">${studioTab==='have'?`<div class="field"><label for="raw">متن سناریو، کپشن یا ایده *</label><textarea id="raw" name="raw" rows="7" required placeholder="متن خام خود را اینجا بنویسید...">${esc(editItem?.body||selected?.title||'')}</textarea></div>`:`<div class="field"><label for="topic">موضوع *</label><input id="topic" name="topic" required value="${esc(selected?.title||'')}" placeholder="مثلاً انتخاب موضوع دوره آموزشی"></div><div class="field"><label for="audience">مخاطب هدف</label><input id="audience" name="audience" value="${esc(product.brand.audience)}"></div>${selectField('duration','مدت محتوا',['30 ثانیه','60 ثانیه','90 ثانیه','3 دقیقه'])}<div class="field"><label for="product">محصول یا خدمت مرتبط</label><input id="product" name="product" value="${esc(product.brand.product)}"></div>${selectField('awareness','آشنایی مخاطب با موضوع',['تازه‌کار','آشنا','حرفه‌ای'])}`}<div class="form-columns">${selectField('goal','هدف محتوا',['آگاهی','تعامل','اعتماد','اعتبار','فروش'])}${selectField('format','فرمت محتوا',['ریلز','پست اسلایدی','استوری','لایو'])}</div><div class="field"><label for="cta">دعوت به اقدام موردنظر</label><input id="cta" name="cta" placeholder="مثلاً سؤال خود را در دیدگاه بنویسید"></div>${studioTab==='have'?'<div class="field"><label for="locked">بخش‌هایی که نباید تغییر کنند</label><textarea id="locked" name="locked" rows="2" placeholder="عبارت‌های دقیق یا پیام‌های کلیدی"></textarea></div>':''}<div class="field"><label for="tone">لحن موردنظر</label><input id="tone" name="tone" value="${esc(product.brand.tone)}"></div>${studioTab==='have'?'<label class="check-control"><input type="checkbox" name="preserve" checked> پیام اصلی من را حفظ کن</label>':''}<button type="submit" class="btn btn-dark">ساخت پیش‌نویس ساختاری ${icon('arrow')}</button></form></section><section class="panel" id="studio-result"><h2>خروجی سناریو</h2>${studioDraft?renderDraft():`<div class="empty-state">${icon('spark')}<h3>پیش‌نویس شما اینجا آماده می‌شود</h3><p>پس از تکمیل فرم، سناریو را بازبینی و در کتابخانه ذخیره کنید.</p></div>`}</section></div>`};
function renderDraft(){const d=studioDraft;if(!d)return '';const topic=esc(d.topic),call=esc(d.cta||'برای ادامه این موضوع، سؤال خود را بنویسید.');return `<div class="notice">پیش‌نویس قالبی است؛ پیش از انتشار، صحت ادعاها و تناسب با تجربه واقعی خودتان را بررسی کنید.</div>${d.mode==='new'?`<h3>3 زاویه پیشنهادی</h3><div class="chip-row">${['از تجربه شخصی','اشتباه رایج','پرسش مخاطب'].map((v,i)=>`<button type="button" class="chip ${d.angle===i?'chosen':''}" data-angle="${i}">${v}</button>`).join('')}</div>`:''}<h3>هوک پیشنهادی</h3><p>${d.mode==='have'?'چرا این موضوع برای مخاطب شما مهم است؟':`پیش از تصمیم‌گیری درباره «${topic}»، این نکته را در نظر بگیرید.`}</p><p><strong>هوک‌های جایگزین:</strong> رایج‌ترین سؤال درباره «${topic}» چیست؟ · برای شروع «${topic}» از کجا باید آغاز کرد؟</p><h3>ساختار و سناریوی کامل</h3><div class="draft-text">${d.mode==='have'?`<p><strong>متن مبنا:</strong> ${esc(d.raw)}</p><p>${d.preserve?'پیام اصلی بدون تغییر حفظ می‌شود و فقط ترتیب ارائه منظم شده است.':'می‌توانید متن را با ترتیب مسئله، مثال و قدم بعدی بازنویسی کنید؛ بدون افزودن ادعای تازه.'}</p><p>ابتدا مسئله را روشن کنید؛ سپس همین پیام را با یک تجربه یا مثال واقعی بیان کنید؛ در پایان مخاطب را به یک قدم مشخص دعوت کنید.</p>${d.locked?`<p>بخش‌های بدون تغییر: ${esc(d.locked)}</p>`:''}`:`<p><strong>شروع:</strong> موضوع «${topic}» را با زاویه «${['تجربه شخصی','اشتباه رایج','پرسش مخاطب'][d.angle]}» معرفی کنید.</p><p><strong>میانه:</strong> یک مثال واقعی از تجربه خودتان و یک نکته کاربردی درباره ${topic} اضافه کنید.</p><p><strong>پایان:</strong> نتیجه را خلاصه کنید و دعوت به اقدام مرتبط بدهید.</p>`}</div><p><strong>تقسیم زمانی برای ریلز:</strong> 0–5 ثانیه هوک · 5–20 ثانیه مسئله · 20–45 ثانیه مثال · 45–60 ثانیه جمع‌بندی و دعوت به اقدام. برای فرمت‌های دیگر، این ترتیب را به اسلاید یا بخش تبدیل کنید.</p><p><strong>متن روی ویدئو یا اسلاید:</strong> ${topic}؛ مسئله، تجربه، راهکار.</p><p><strong>کپشن پیشنهادی:</strong> ${topic} موضوعی است که ارزش دارد با تجربه‌های واقعی درباره‌اش گفتگو کنیم. شما چه تجربه‌ای دارید؟</p><p><strong>دعوت به اقدام:</strong> ${call}</p><p><strong>پیشنهاد اجرا:</strong> با مثال واقعی و لحن ${esc(d.tone||'حرفه‌ای')} صحبت کنید؛ از وعده قطعی خودداری کنید.</p><p><strong>تغییرات:</strong> متن در قالب مسئله، مثال و قدم بعدی سامان‌دهی شده؛ ادعای جدیدی به پیام شما اضافه نشده است.</p><span class="tag">هم‌راستا با هدف ${esc(d.goal)} · نیازمند بازبینی شما</span>${d.mode==='new'?`<h3>3 استوری مکمل</h3><p>1. نظرسنجی درباره مسئله · 2. مثال کوتاه · 3. پاسخ به یک سؤال پرتکرار</p><p><strong>محتوای بعدی:</strong> یک تجربه واقعی مرتبط با ${topic} را روایت کنید.</p>`:''}<div class="card-actions"><button class="btn btn-dark btn-sm" type="button" data-action="save-draft">ذخیره در کتابخانه</button><button class="btn btn-outline btn-sm" type="button" data-action="calendar-draft">افزودن به تقویم</button></div>`}
appPages.library=()=>{const q=libraryFilters.q.toLowerCase(),items=product.library.filter(v=>(!q||v.title.toLowerCase().includes(q))&&(!libraryFilters.type||v.type===libraryFilters.type)&&(!libraryFilters.status||v.status===libraryFilters.status)&&(!libraryFilters.goal||v.goal===libraryFilters.goal));return `${appTitle('کتابخانه محتوا','ایده‌ها، سناریوها و محتوای ذخیره‌شده را یکجا مدیریت کنید.',link('studio','ساخت محتوای جدید'))}<div class="filter-row"><label>جست‌وجو<input type="search" id="library-search" value="${esc(libraryFilters.q)}" placeholder="جست‌وجوی عنوان"></label>${[['type','نوع',['ایده','سناریو','کپشن','استوری']],['status','وضعیت',['پیش‌نویس','آماده ضبط','زمان‌بندی‌شده','منتشرشده']],['goal','هدف',['آگاهی','تعامل','اعتماد','اعتبار','فروش']]].map(([key,label,values])=>`<label>${label}<select data-library-filter="${key}">${options(values,libraryFilters[key],'همه')}</select></label>`).join('')}</div><div class="panel">${items.length?items.map(v=>`<div class="library-card"><div><strong>${esc(v.title)}</strong><div class="card-meta"><span class="tag">${esc(v.type)}</span><span>${esc(v.goal)}</span><span>آخرین ویرایش: ${esc(v.updated)}</span></div></div><label class="sr-only" for="status-${esc(v.id)}">وضعیت ${esc(v.title)}</label><select id="status-${esc(v.id)}" data-content-status="${esc(v.id)}">${['پیش‌نویس','آماده ضبط','زمان‌بندی‌شده','منتشرشده'].map(status=>`<option ${v.status===status?'selected':''}>${status}</option>`).join('')}</select><div class="card-actions"><a class="inline-link" href="#/app/studio?edit=${encodeURIComponent(v.id)}">ادامه ویرایش</a><button type="button" data-action="plan-content" data-id="${esc(v.id)}">افزودن به تقویم</button><button type="button" class="danger-link" data-action="remove-content" data-id="${esc(v.id)}">حذف</button></div></div>`).join(''):emptyPanel('کتابخانه هنوز خالی است','یک ایده ذخیره کنید یا اولین سناریوی خود را بسازید.','ideas','دیدن ایده‌ها')}</div>`};
let libraryFilters={q:'',type:'',status:'',goal:''};
function localDay(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function weekDays(){const start=new Date();start.setHours(12,0,0,0);start.setDate(start.getDate()-(start.getDay()+1)%7);return Array.from({length:7},(_,i)=>{const day=new Date(start);day.setDate(start.getDate()+i);return day})}
const weekNames=['شنبه','یکشنبه','دوشنبه','سه‌شنبه','چهارشنبه','پنجشنبه','جمعه'];
let selectedDay=localDay(new Date());
appPages.calendar=()=>{const days=weekDays(),all=[...product.library.map(v=>({id:v.id,title:v.title,goal:v.goal})),...sampleIdeas.map((v,i)=>({id:`idea-${i}`,title:v.title,goal:v.goal,type:v.type}))];return `${appTitle('تقویم محتوا','برنامه هفته را بچینید و زمان انتشار را به سادگی جابه‌جا کنید.',`<button type="button" class="btn btn-dark" data-action="suggest-week">تولید برنامه پیشنهادی هفته</button>`)}<div class="notice">برنامه پیشنهادی فقط نمونه چیدمان است؛ هیچ محتوایی خودکار منتشر نمی‌شود.</div><div class="calendar-grid">${days.map((day,i)=>{let date=localDay(day),entries=product.calendar.filter(x=>x.date===date);return `<section class="calendar-day"><h2>${weekNames[i]} <span>${new Intl.DateTimeFormat('fa-IR-u-nu-latn',{day:'numeric',month:'short'}).format(day)}</span></h2>${entries.map(x=>`<div class="calendar-entry"><strong>${esc(x.title)}</strong><small>${esc(x.goal)} · ${esc(x.status||'پیش‌نویس')}</small><label class="sr-only" for="move-${esc(x.id)}">جابه‌جایی ${esc(x.title)}</label><select id="move-${esc(x.id)}" data-move="${esc(x.id)}">${days.map((d,j)=>`<option value="${localDay(d)}" ${x.date===localDay(d)?'selected':''}>${weekNames[j]}</option>`).join('')}</select><button type="button" class="danger-link" data-action="remove-plan" data-id="${esc(x.id)}">برداشتن از برنامه</button></div>`).join('')}<button type="button" class="day-add" data-action="select-day" data-date="${date}">+ افزودن محتوا</button></section>`}).join('')}</div><div class="app-grid"><section class="panel"><h2>افزودن محتوا به برنامه</h2><form id="calendar-form"><div class="field"><label for="calendar-item">ایده یا سناریو</label><select id="calendar-item" name="item" required>${all.map(v=>`<option value="${esc(v.id)}">${esc(v.title)}</option>`).join('')}</select></div><div class="field"><label for="calendar-date">روز انتشار</label><select id="calendar-date" name="date">${days.map((d,i)=>`<option value="${localDay(d)}" ${selectedDay===localDay(d)?'selected':''}>${weekNames[i]}</option>`).join('')}</select></div><button class="btn btn-dark btn-sm" type="submit">افزودن به تقویم</button></form></section><section class="panel"><h2>تعادل محتوای هفته</h2><p>آموزشی، شخصی، اعتمادساز، فروش و تعاملی</p>${[['آموزشی',['آگاهی','اعتبار']],['شخصی',['تجربه شخصی']],['اعتمادساز',['اعتماد']],['فروش',['فروش']],['تعاملی',['تعامل']]].map(([name,goals])=>`<div class="insight-row"><span>${name}</span><strong>${product.calendar.filter(x=>days.some(d=>localDay(d)===x.date)&&(name==='شخصی'?goals.includes(x.type):goals.includes(x.goal))).length} محتوا</strong></div>`).join('')}</section></div>`};
appPages.onboarding=()=>`${appTitle('آنبوردینگ برند','یک مسیر ساده برای شروع، حتی بدون اتصال اینستاگرام.') }<div class="notice">مرحله 1 از 2: تکمیل دستی اطلاعات برند · مرحله 2: بازبینی و شروع. اتصال اینستاگرام اختیاری است.</div><div class="demo-switch"><button type="button" class="inline-link" data-action="restore-sample">بازگشت به داده‌های نمونه</button></div>${brandForm(true)}`;
function brandForm(onboarding=false){return `<form class="panel brand-form" id="brand-form"><h2>${onboarding?'برندتان را معرفی کنید':'ویرایش اطلاعات برند'}</h2><p>این اطلاعات تا بستن صفحه در دسترس‌اند؛ فقط با رضایت شما در همین مرورگر نگهداری می‌شوند.</p><div class="form-columns">${[['name','نام برند'],['field','حوزه تخصص'],['product','محصول یا خدمات'],['audience','مخاطب هدف'],['goal','هدف سه‌ماهه'],['tone','لحن برند']].map(([key,label])=>`<div class="field"><label for="brand-${key}">${label}${['name','field','audience'].includes(key)?' *':''}</label><input id="brand-${key}" name="${key}" value="${esc(product.brand[key])}" ${['name','field','audience'].includes(key)?'required':''} placeholder="${label}"></div>`).join('')}</div><div class="field"><label for="brand-bio">متن بیو</label><textarea id="brand-bio" name="bio" rows="3" placeholder="متن معرفی پیج شما">${esc(product.brand.bio)}</textarea></div><div class="field"><label for="brand-sample">نمونه سناریو یا محتوای قبلی</label><textarea id="brand-sample" name="sample" rows="3" placeholder="یک متن کوتاه از محتوایتان">${esc(product.brand.sample)}</textarea></div><div class="card-actions"><button class="btn btn-dark" type="submit">${onboarding?'ذخیره و شروع':'ذخیره تغییرات'}</button>${onboarding?link('connection','راهنمای اتصال اختیاری','btn btn-outline'):''}</div></form>`}
appPages.connection=()=>`${appTitle('اتصال اینستاگرام','آشنایی با مسیر اتصال امن اکانت حرفه‌ای.',link('onboarding','ادامه بدون اتصال','btn btn-outline'))}<div class="app-grid"><section class="panel"><span class="tag">اتصال امن اینستاگرام</span><h2>اتصال رسمی از طریق صفحه مجوز اینستاگرام</h2><p>برای تحلیل دقیق‌تر، اکانت حرفه‌ای اینستاگرام خود را متصل کنید.</p><ul class="check-list"><li>${icon('check')} برندیار هرگز رمز عبور شما را دریافت یا ذخیره نمی‌کند.</li><li>${icon('check')} مجوزها باید در صفحه رسمی سرویس مشخص و تأیید شوند.</li><li>${icon('check')} می‌توانید هر زمان اتصال را قطع کنید.</li></ul><div class="notice">در این نسخه اتصال واقعی و همگام‌سازی فعال نیست. دکمه اتصال تا راه‌اندازی جریان رسمی غیرفعال است.</div><button type="button" class="btn btn-dark" disabled>اتصال امن اینستاگرام · به‌زودی</button></section><section class="panel"><h2>بدون اتصال هم شروع کنید</h2><p>پروفایل برند را دستی تکمیل کنید و از مسیر نمونه استفاده کنید.</p><ul class="check-list"><li>${icon('check')} بیو و حوزه تخصص</li><li>${icon('check')} محصولات و مخاطب هدف</li><li>${icon('check')} هدف سه‌ماهه و نمونه محتوا</li></ul>${link('onboarding','تکمیل دستی پروفایل')}<hr><p>وضعیت اتصال: متصل نیست<br>آخرین همگام‌سازی: انجام نشده</p><button type="button" class="btn btn-outline btn-sm" disabled>اتصال مجدد / قطع اتصال · غیرفعال</button></section></div>`;
appPages.subscription=()=>`${appTitle('اشتراک و پرداخت','وضعیت طرح و جزئیات انتخاب اشتراک.',`<a class="btn btn-outline" href="#/pricing">دیدن تعرفه‌ها</a>`)}<div class="app-grid"><section class="panel"><h2>طرح فعلی: پیش‌نمایش</h2><p>در این نسخه هیچ اشتراک یا پرداخت واقعی ثبت نشده است.</p><div class="notice">طرح حرفه‌ای 7,990,000 تومان در ماه · پلن سفارشی پس از بررسی نیازها قیمت‌گذاری می‌شود.</div><a class="btn btn-outline btn-sm" href="#/pricing">مقایسه طرح‌ها</a></section><section class="panel"><h2>سوابق پرداخت</h2><div class="empty-state">${icon('book')}<h3>تراکنشی وجود ندارد</h3><p>پرداخت در نسخه نمایشی فعال نیست.</p></div></section></div>`;
appPages.settings=()=>`${appTitle('پروفایل و تنظیمات','اطلاعات برند، تنظیمات حساب و حریم خصوصی را مدیریت کنید.',link('onboarding','راهنمای شروع','btn btn-outline'))}<div class="settings-grid"><div>${brandForm()}</div><div><section class="panel"><h2>اطلاعات حساب</h2><p>در نسخه نمایشی حساب واقعی ساخته نشده است.</p><div class="insight-row"><span>نام برند</span><strong>${esc(product.brand.name||'وارد نشده')}</strong></div><div class="insight-row"><span>هدف</span><strong>${esc(product.brand.goal||'وارد نشده')}</strong></div></section><section class="panel"><h2>اتصال اینستاگرام</h2><p>متصل نیست · آخرین همگام‌سازی: انجام نشده</p>${link('connection','راهنمای اتصال امن','btn btn-outline btn-sm')}</section><section class="panel"><h2>اعلان‌ها و اشتراک</h2><label class="check-control"><input id="notify-check" type="checkbox" ${product.notifications?'checked':''}> یادآوری برنامه محتوا در این پیش‌نمایش</label><p>اعلان بیرونی ارسال نمی‌شود.</p>${link('subscription','مدیریت اشتراک','btn btn-outline btn-sm')}</section><section class="panel"><h2>حریم خصوصی و داده‌ها</h2><label class="check-control"><input id="consent-check" type="checkbox" ${product.consent?'checked':''}> ذخیره اطلاعات نمایشی در این مرورگر پس از بستن صفحه</label><p>هیچ داده‌ای در این نسخه به سرویس دیگری ارسال نمی‌شود.</p><div class="card-actions"><button type="button" class="btn btn-outline btn-sm" data-action="export">خروجی داده‌ها</button><button type="button" class="btn btn-outline btn-sm danger-link" data-action="reset-account">حذف داده‌های محلی</button></div><p class="hint">حذف حساب واقعی در این پیش‌نمایش وجود ندارد؛ این گزینه فقط داده‌های همین مرورگر را پاک می‌کند.</p></section><section class="panel"><h2>تماس با پشتیبانی</h2><p>برای آشنایی با راه‌های ارتباطی به صفحه تماس بروید.</p><a class="inline-link" href="#/contact">صفحه تماس با ما</a></section></div></div>`;
pages.contact=()=>`${pageHero('تماس با ما','گفتگو، بهترین نقطه شروع است','برای پرسش درباره محصول یا همکاری، موضوع خود را ثبت کنید.') }<section class="section"><div class="container"><div class="panel contact-panel"><h2>پیام شما</h2><div class="notice">در این پیش‌نمایش ارسال پیام به پشتیبانی فعال نیست. اطلاعاتی که وارد کنید ارسال یا ذخیره نمی‌شود.</div><form id="contact-form"><div class="field"><label for="contact-name">نام</label><input id="contact-name" required></div><div class="field"><label for="contact-email">ایمیل</label><input id="contact-email" type="email" required></div><div class="field"><label for="contact-message">پیام</label><textarea id="contact-message" required rows="5"></textarea></div><button class="btn btn-dark" type="submit">ثبت پیام نمایشی</button></form></div></div></section>`;
pages.terms=()=>`${pageHero('قوانین استفاده','شرایط استفاده از نسخه نمایشی','این صفحه وضعیت فعلی محصول را به‌روشنی توضیح می‌دهد.') }<section class="section"><div class="container legal-copy panel"><h2>دامنه پیش‌نمایش</h2><p>این سایت ارزیابی اولیهٔ خوداظهاری و گزارش پیشنهادی قابل دانلود ارائه می‌کند؛ ثبت‌نام، پرداخت، رزرو جلسه، تحلیل خودکار پیج و اتصال اینستاگرام فعال نیستند. بخش داشبورد صرفاً پیش‌نمایش رابط با داده‌های نمونه است.</p><h2>مسئولیت محتوا</h2><p>پیشنهادهای محتوایی و سناریوهای قالبی باید پیش از انتشار توسط شما بازبینی شوند. محصول وعده قطعی افزایش بازدید، دنبال‌کننده یا فروش نمی‌دهد.</p><h2>تغییرات آینده</h2><p>شرایط نهایی سرویس هنگام راه‌اندازی واقعی همراه با جزئیات خدمات و پشتیبانی منتشر خواهد شد.</p></div></section>`;
pages.privacy=()=>`${pageHero('حریم خصوصی','شفافیت درباره داده‌های شما','در این پیش‌نمایش کنترل اطلاعات واردشده در اختیار خودتان است.') }<section class="section"><div class="container legal-copy panel"><h2>داده‌های این نسخه</h2><p>پاسخ‌های ارزیابی رایگان و گزارش آن فقط تا بستن همین تب در حافظه نگه داشته می‌شوند؛ به سرور ارسال نمی‌شوند و با بستن یا بارگذاری دوبارهٔ صفحه از بین می‌روند. از فرم ارزیابی برای واردکردن اطلاعات خصوصی دیگران استفاده نکنید. در صورت فعال‌کردن رضایت در تنظیمات پیش‌نمایش، اطلاعات برند، چک‌لیست‌ها، ایده‌های ذخیره‌شده و تقویم تنها در حافظه همین مرورگر نگهداری می‌شوند. در غیر این صورت با بستن صفحه باقی نمی‌مانند. رمز ورود کارکنان فقط برای احراز هویت به سرور ارسال می‌شود و در مرورگر ذخیره نمی‌شود.</p><h2>اینستاگرام</h2><p>هیچ اتصال یا همگام‌سازی واقعی در این نسخه انجام نمی‌شود. برندیار هرگز رمز عبور اینستاگرام شما را درخواست نمی‌کند.</p><h2>اختیار شما</h2><p>در تنظیمات، می‌توانید از داده‌های محلی خروجی بگیرید یا پس از تأیید، همه داده‌های نمایشی را حذف کنید. سیاست نهایی هنگام عرضه سرویس واقعی منتشر می‌شود.</p></div></section>`;
appPages['onboarding-review']=()=>`${appTitle('بازبینی برند','مرحله 2 از 2 · اطلاعات برندتان را مرور و مسیر را آغاز کنید.') }<div class="panel settings-panel"><h2>${esc(product.brand.name||'برند شما')}</h2><div class="insight-row"><span>حوزه</span><strong>${esc(product.brand.field)}</strong></div><div class="insight-row"><span>مخاطب</span><strong>${esc(product.brand.audience)}</strong></div><div class="insight-row"><span>محصول</span><strong>${esc(product.brand.product||'ثبت نشده')}</strong></div><div class="insight-row"><span>هدف سه‌ماهه</span><strong>${esc(product.brand.goal||'ثبت نشده')}</strong></div><div class="notice">تحلیل و ایده‌های موجود همچنان نمونه‌اند و از اطلاعات واردشده شما محاسبه نشده‌اند.</div><div class="card-actions">${link('onboarding','اصلاح اطلاعات','btn btn-outline')}${link('app','ورود به داشبورد')}</div></div>`;
pages['instagram-guide']=()=>`${pageHero('راهنمای اتصال اینستاگرام','اتصال امن، با اختیار شما','برای تحلیل دقیق‌تر، اکانت حرفه‌ای اینستاگرام خود را متصل کنید.') }<section class="section"><div class="container legal-copy panel"><h2>اتصال رسمی چگونه انجام می‌شود؟</h2><p>پس از فعال‌شدن سرویس، کاربر از صفحه رسمی مجوز دسترسی عبور می‌کند و دسترسی‌های لازم را می‌بیند و تأیید می‌کند. برندیار هرگز رمز عبور شما را دریافت یا ذخیره نمی‌کند.</p><h2>انتخاب با شماست</h2><p>می‌توانید هر زمان اتصال را قطع کنید. برای شروع بدون اتصال هم کافی است پروفایل برند را دستی تکمیل کنید.</p><div class="notice">در نسخه پیش‌نمایش، اتصال و همگام‌سازی واقعی فعال نیست.</div><a class="btn btn-dark" href="#/app/connection">دیدن مسیر نمایشی اتصال</a></div></section>`;
pages.loading=()=>`${pageHero('وضعیت بارگذاری','در حال آماده‌سازی اطلاعات','این صفحه نمونه‌ای از وضعیت بارگذاری است؛ درخواست زنده‌ای در این نسخه انجام نمی‌شود.') }<section class="section"><div class="container legal-copy panel"><div class="skeleton" aria-label="نمونه وضعیت بارگذاری"></div><div class="skeleton short"></div><a class="btn btn-outline" href="#/">بازگشت به خانه</a></div></section>`;
appPages.loading=()=>`${appTitle('در حال آماده‌سازی','این یک نمونه حالت بارگذاری است؛ داده‌ای از سرور دریافت نمی‌شود.') }<div class="panel"><div class="skeleton"></div><div class="skeleton short"></div>${link('app','بازگشت به داشبورد')}</div>`;
let motionObserver;
function setupHeroMotion(){const visual=document.querySelector('.hero-visual');if(!visual)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;requestAnimationFrame(()=>visual.classList.add('hero-ready'));if(reduced||!window.matchMedia('(min-width: 801px) and (hover: hover) and (pointer: fine)').matches)return;visual.addEventListener('pointermove',event=>{const rect=visual.getBoundingClientRect();visual.style.setProperty('--glow-x',`${(event.clientX-rect.left)/rect.width*100}%`);visual.style.setProperty('--glow-y',`${(event.clientY-rect.top)/rect.height*100}%`);const x=Math.max(-.5,Math.min(.5,(event.clientX-rect.left)/rect.width-.5)),y=Math.max(-.5,Math.min(.5,(event.clientY-rect.top)/rect.height-.5));visual.style.setProperty('--card-rotate-x',`${-y*8}deg`);visual.style.setProperty('--card-rotate-y',`${x*8}deg`);visual.style.setProperty('--card-shift-x',`${x*14}px`);visual.style.setProperty('--card-shift-y',`${y*10}px`);visual.style.setProperty('--card-shadow-x',`${-x*24}px`);visual.style.setProperty('--card-shadow-y',`${28+y*12}px`)});visual.addEventListener('pointerleave',()=>{for(const name of ['--glow-x','--glow-y','--card-rotate-x','--card-rotate-y','--card-shift-x','--card-shift-y','--card-shadow-x','--card-shadow-y'])visual.style.removeProperty(name)})}
function setupMotion(){if(motionObserver)motionObserver.disconnect();const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;const selectors=['.by-section-heading','.by-scene','.hero-copy','.trust-inner','.page-hero .container','.section-heading','.feature-card','.split > *','.step-card','.price-card','.faq-list details','.cta-block','.app-heading','.app-banner','.metric-card','.app-grid > .panel','.roadmap-stage','.analysis-card','.calendar-day','.settings-grid > *'];const items=[...new Set(selectors.flatMap(selector=>[...document.querySelectorAll(selector)]))];items.forEach((item,index)=>{item.classList.add('motion-item');if(item.closest('.hero'))item.classList.add('motion-hero');item.style.setProperty('--motion-delay',`${Math.min(index%4,3)*70}ms`)});if(reduced||!('IntersectionObserver' in window)){items.forEach(item=>item.classList.add('is-visible'));return}motionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');motionObserver.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -7%'});items.forEach(item=>motionObserver.observe(item))}
