document.addEventListener('submit',event=>{if(event.target.id!=='assessment-step-form')return;event.preventDefault();const question=assessmentFlow()[assessmentStep],form=event.target,values=new FormData(form);let answer;if(question.type==='multi'){answer=values.getAll('answer').map(v=>question.options[Number(v)]);if(!answer.length||question.max&&answer.length>question.max){form.querySelector('#assessment-feedback').textContent=question.max?`حداکثر ${question.max} گزینه انتخاب کن.`:'یک گزینه انتخاب کن یا «هیچ‌کدام» را بزن.';return}}else if(question.type==='text'||question.type==='textarea'){answer=question.skip&&values.has('skip')?question.skip:String(values.get('answer')||'').trim();if(!answer&&!question.optional){form.querySelector('#assessment-feedback').textContent='می‌توانی یک پاسخ کوتاه بنویسی یا گزینهٔ کمکی را انتخاب کنی.';return}}else{answer=values.has('answer')?question.options[Number(values.get('answer'))]:'';if(!answer&&!question.optional){form.querySelector('#assessment-feedback').textContent='یک گزینه انتخاب کن تا ادامه بدهیم.';return}}assessmentAnswers[question.id]=answer||'';if(question.extra)assessmentAnswers.q2extra=String(values.get('extra')||'').trim();if(question.id==='q11'){if(!offersService(assessmentAnswers))for(const id of ['q12','q13','q14'])delete assessmentAnswers[id];else delete assessmentAnswers.q12a}if(assessmentStep===assessmentFlow().length-1){assessmentResult={...assessmentAnswers};location.hash='#/report';return}assessmentStep++;updateAssessment()});
document.addEventListener('change',event=>{const input=event.target,form=input.closest('#assessment-step-form');if(!form)return;const question=assessmentFlow()[assessmentStep];if(input.name==='skip'){const text=form.querySelector('#assessment-answer');text.disabled=input.checked;text.required=!input.checked;if(input.checked)text.value=''}if(question.type==='multi'&&input.name==='answer'&&question.none&&input.checked){const inputs=[...form.querySelectorAll('[name=answer]')];if(question.options[Number(input.value)]===question.none)inputs.forEach(other=>{if(other!==input)other.checked=false});else inputs[question.options.indexOf(question.none)].checked=false}if(question.max&&form.querySelectorAll('[name=answer]:checked').length>question.max){input.checked=false;form.querySelector('#assessment-feedback').textContent=`حداکثر ${question.max} گزینه انتخاب کن.`}else form.querySelector('#assessment-feedback').textContent=''});
document.addEventListener('click',event=>{if(event.target.id==='assessment-edit'){assessmentStep=0}else if(event.target.id==='assessment-prev'){assessmentStep=Math.max(0,assessmentStep-1);updateAssessment()}else if(event.target.id==='assessment-clear'){assessmentResult=null;assessmentAnswers={};assessmentStep=0;location.hash='#/assessment';route()}else if(event.target.id==='assessment-download'&&assessmentResult){const text=['گزارش اولیهٔ برندیار','این پیشنهادها فقط بر اساس پاسخ‌های خودت ساخته شده‌اند.','','سه قدم پیشنهادی:',...assessmentSteps(assessmentResult).map((step,index)=>`${index+1}. ${step}`)].join('\n'),url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),anchor=document.createElement('a');anchor.href=url;anchor.download='brandyar-steps.txt';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}});
