function route(){const path=location.hash.replace(/^#\/?/,'').split('?')[0].replace(/^\/+|\/+$/g,'');const isApp=path==='app'||path.startsWith('app/');document.getElementById('site-shell').hidden=isApp;document.getElementById('app-shell').hidden=!isApp;closeSiteMenu();if(isApp){const key=path.split('/')[1]||'app';if(key==='studio'&&activeStudioKey!==location.hash){studioDraft=null;activeStudioKey=location.hash}document.getElementById('app-main').innerHTML=`<div class="app-main-inner">${appPages[key]?appPages[key]():`<div class="not-found"><h1>صفحه پیدا نشد</h1><a href="#/app" class="btn btn-dark">بازگشت به داشبورد</a></div>`}</div>`;document.querySelectorAll('[data-app]').forEach(a=>{let active=a.dataset.app===key;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')})}else{document.getElementById('main').innerHTML=pages[path]?pages[path]():(path.startsWith('features/')?pages['features']():`<div class="not-found"><h1>این صفحه پیدا نشد</h1><a href="#/" class="btn btn-dark">بازگشت به خانه</a></div>`);document.querySelectorAll('[data-link]').forEach(a=>{let active=a.dataset.link===(path||'home');a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current')})}document.title=`${({app:'نمای کلی',analysis:'تحلیل برند',ideas:'ایده‌های محتوا',roadmap:'نقشه راه',library:'کتابخانه محتوا',studio:'استودیوی سناریو',calendar:'تقویم محتوا',onboarding:'شروع کار','onboarding-review':'بازبینی برند',connection:'اتصال اینستاگرام',subscription:'اشتراک',contact:'تماس با ما','instagram-guide':'راهنمای اتصال اینستاگرام',loading:'در حال بارگذاری',terms:'قوانین استفاده',privacy:'حریم خصوصی',settings:'پروفایل و تنظیمات',features:'امکانات','features/brand-analysis':'تحلیل دقیق برند','features/content-ideas':'ایده‌هایی که به تو می‌آیند','features/growth-roadmap':'نقشه راه قابل اجرا','how-it-works':'نحوه کار',pricing:'تعرفه‌ها',faq:'سؤالات متداول',about:'درباره ما',login:'ورود',signup:'ثبت‌نام'})[path]||({features:'امکانات','features/brand-analysis':'تحلیل دقیق برند','features/content-ideas':'ایده‌هایی که به تو می‌آیند','features/growth-roadmap':'نقشه راه قابل اجرا'})[path]||'پرسونال برندت را آگاهانه بساز'} | برندیار`;window.scrollTo(0,0);setupMotion();setupHeroMotion()}
