document.getElementById('skip-link').addEventListener('click',e=>{e.preventDefault();document.getElementById(document.getElementById('app-shell').hidden?'main':'app-main').focus()});
document.getElementById('menu-toggle').addEventListener('click',()=>{const menu=document.getElementById('site-nav'),toggle=document.getElementById('menu-toggle');if(menu.classList.contains('open')){closeSiteMenu(true);return}menu.classList.add('open');toggle.setAttribute('aria-expanded','true');toggle.setAttribute('aria-label','بستن منو');menu.querySelector('a')?.focus()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('site-nav').classList.contains('open'))closeSiteMenu(true)});document.addEventListener('click',e=>{const menu=document.getElementById('site-nav');if(!menu.classList.contains('open'))return;if(menu.contains(e.target)){if(e.target.closest('a')){closeSiteMenu();setTimeout(()=>document.getElementById(document.getElementById('app-shell').hidden?'main':'app-main').focus(),0)}return}if(!e.target.closest('#menu-toggle'))closeSiteMenu(true)});document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const form=e.target,feedback=document.getElementById('form-feedback');if(location.hash.includes('signup')){feedback.textContent='ثبت‌نام هنوز فعال نیست؛ می‌توانی پیش‌نمایش داشبورد را ببینی.';return}const submit=form.querySelector('[type="submit"]');submit.disabled=true;feedback.textContent='در حال بررسی ورود...';try{const response=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({email:form.elements.namedItem('email').value,password:form.elements.namedItem('password').value})});form.elements.namedItem('password').value='';if(!response.ok){feedback.textContent='اطلاعات ورود معتبر نیست یا تلاش‌های زیادی انجام شده است.';return}const code=window.prompt('کد یک‌بارمصرف برنامه احراز هویت را وارد کنید:');if(!code){feedback.textContent='تأیید دومرحله‌ای تکمیل نشد.';return}const verified=await fetch('/api/auth/mfa/verify',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({code})});if(!verified.ok){feedback.textContent='کد تأیید معتبر نیست یا مهلت آن گذشته است.';return}location.assign('/admin')}catch{feedback.textContent='سرویس ورود در دسترس نیست؛ پیش‌نمایش داشبورد همچنان قابل مشاهده است.'}finally{submit.disabled=false}});document.addEventListener('click',e=>{const button=e.target.closest('[data-save]');if(!button)return;const item=ideas[Number(button.dataset.save)];if(!item)return;let saved=[];try{saved=JSON.parse(localStorage.getItem('brandyar-saved-ideas')||'[]')}catch{}if(!Array.isArray(saved))saved=[];if(!saved.includes(item[0])){saved.push(item[0]);localStorage.setItem('brandyar-saved-ideas',JSON.stringify(saved))}button.textContent='ذخیره شد';button.disabled=true});let headerScrollFrame=0;function updateHeaderScroll(){headerScrollFrame=0;document.body.classList.toggle('has-scrolled',window.scrollY>32)}window.addEventListener('scroll',()=>{if(!headerScrollFrame)headerScrollFrame=requestAnimationFrame(updateHeaderScroll)},{passive:true});updateHeaderScroll();window.addEventListener('hashchange',route);route();
function refresh(){route()}
function addLibrary(item){const id=item.id||`content-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;product.library.unshift({...item,id,status:item.status||'پیش‌نویس',updated:new Intl.DateTimeFormat('fa-IR-u-nu-latn',{day:'numeric',month:'long'}).format(new Date())});persist();return id}
function scheduleItem(item,date=selectedDay){product.calendar.push({id:`plan-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,contentId:item.id,title:item.title,goal:item.goal,type:item.type||'',date,status:'پیش‌نویس'});persist()}
document.addEventListener('change',e=>{const target=e.target;if(target.dataset.task){product.tasks[target.dataset.task]=target.value;persist();refresh();notify('وضعیت اقدام ذخیره شد')}else if(target.dataset.filter){ideaFilters[target.dataset.filter]=target.value;refresh()}else if(target.dataset.libraryFilter){libraryFilters[target.dataset.libraryFilter]=target.value;refresh()}else if(target.dataset.contentStatus){const item=product.library.find(v=>v.id===target.dataset.contentStatus);if(item){item.status=target.value;persist();refresh();notify('وضعیت محتوا به‌روز شد')}}else if(target.dataset.move){const item=product.calendar.find(v=>v.id===target.dataset.move);if(item){item.date=target.value;persist();refresh();notify('محتوا به روز جدید منتقل شد')}}else if(target.id==='library-search'){libraryFilters.q=target.value.trim();refresh()}else if(target.id==='notify-check'){product.notifications=target.checked;persist();notify('تنظیم یادآوری ذخیره شد')}else if(target.id==='consent-check'){product.consent=target.checked;if(!target.checked)localStorage.removeItem('brandyar-product-v1');persist();notify(target.checked?'ذخیره‌سازی محلی فعال شد':'ذخیره‌سازی محلی غیرفعال شد و داده‌های ذخیره‌شده پاک شدند')}});
document.addEventListener('submit',e=>{if(e.target.id==='brand-form'){e.preventDefault();const form=new FormData(e.target);for(const key of Object.keys(sampleBrand))product.brand[key]=String(form.get(key)||'').trim();product.mode='custom';persist();location.hash=e.target.closest('#app-main')&&location.hash.includes('/onboarding')?'#/app/onboarding-review':'#/app';refresh();notify('پروفایل برند ذخیره شد؛ تحلیل‌ها همچنان نمونه نمایشی هستند')}else if(e.target.id==='studio-form'){e.preventDefault();const form=new FormData(e.target),raw=String(form.get('raw')||'').trim(),topic=String(form.get('topic')||raw.split('\n')[0]).trim();if(!topic){notify('موضوع یا متن سناریو را وارد کنید');return}studioDraft={mode:studioTab,raw,topic,goal:String(form.get('goal')||'آگاهی'),format:String(form.get('format')||'ریلز'),cta:String(form.get('cta')||''),locked:String(form.get('locked')||''),preserve:form.has('preserve'),tone:String(form.get('tone')||''),angle:0};const button=e.target.querySelector('[type="submit"]');button.disabled=true;button.textContent='در حال آماده‌سازی پیش‌نویس...';setTimeout(()=>{const result=document.getElementById('studio-result');if(result){result.innerHTML='<h2>خروجی سناریو</h2>'+renderDraft();button.disabled=false;button.innerHTML=`ساخت دوباره پیش‌نویس ${icon('arrow')}`;notify('پیش‌نویس آماده شد؛ قبل از انتشار بازبینی کنید')}},250)}else if(e.target.id==='calendar-form'){e.preventDefault();const form=new FormData(e.target),id=String(form.get('item')),date=String(form.get('date')),item=product.library.find(v=>v.id===id)||sampleIdeas.map((v,i)=>({id:`idea-${i}`,title:v.title,goal:v.goal,type:v.type})).find(v=>v.id===id);if(!item||!weekDays().some(day=>localDay(day)===date)){notify('محتوا و روز معتبر را انتخاب کنید');return}scheduleItem(item,date);selectedDay=date;refresh();notify('محتوا به برنامه هفته اضافه شد')}else if(e.target.id==='contact-form'){e.preventDefault();notify('ارسال پیام در نسخه پیش‌نمایش فعال نیست؛ اطلاعات ارسال نشد')}});
document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){studioTab=tab.dataset.tab;studioDraft=null;if(location.hash.includes('?edit='))location.hash='#/app/studio';refresh();return}const angle=e.target.closest('[data-angle]');if(angle&&studioDraft){studioDraft.angle=Number(angle.dataset.angle);document.getElementById('studio-result').innerHTML='<h2>خروجی سناریو</h2>'+renderDraft();return}const quick=e.target.closest('[data-quick-goal]');if(quick){ideaFilters.goal=quick.dataset.quickGoal;refresh();return}const button=e.target.closest('[data-action]');if(!button)return;const id=button.dataset.id;switch(button.dataset.action){case 'fresh-start':if((product.library.length||product.calendar.length||Object.keys(product.tasks).length||product.mode==='custom')&&!window.confirm('نمایش تجربه کاربر جدید، داده‌های فعلی این پیش‌نمایش را جایگزین می‌کند. ادامه می‌دهید؟'))return;product={...defaults,mode:'new',brand:Object.fromEntries(Object.keys(sampleBrand).map(k=>[k,''])),tasks:{},savedIdeas:[],library:[],calendar:[]};persist();refresh();notify('تجربه کاربر جدید فعال شد');break;case 'restore-sample':if((product.library.length||product.calendar.length||Object.keys(product.tasks).length||product.mode==='custom')&&!window.confirm('بازگرداندن داده‌های نمونه، داده‌های فعلی این پیش‌نمایش را جایگزین می‌کند. ادامه می‌دهید؟'))return;product={...defaults,brand:{...sampleBrand},tasks:{},savedIdeas:[],library:[],calendar:[]};persist();location.hash='#/app';refresh();notify('داده‌های نمونه بازگردانده شد');break;case 'save-idea-v2':{const index=Number(id),item=sampleIdeas[index];if(!item)return;if(!product.savedIdeas.includes(index)){product.savedIdeas.push(index);addLibrary({title:item.title,type:'ایده',goal:item.goal,body:item.title,sourceIdea:index})}refresh();notify('ایده در کتابخانه ذخیره شد');break}case 'plan-idea':{const index=Number(id),item=sampleIdeas[index];if(!item)return;scheduleItem({id:`idea-${index}`,title:item.title,goal:item.goal,type:item.type});location.hash='#/app/calendar';refresh();notify('ایده به برنامه هفته اضافه شد');break}case 'clear-filters':ideaFilters={goal:'',format:'',time:'',stage:'',topic:''};refresh();break;case 'save-draft':if(studioDraft){const edit=new URLSearchParams(location.hash.split('?')[1]||'').get('edit'),item=product.library.find(v=>v.id===edit);if(item){Object.assign(item,{title:studioDraft.topic,type:'سناریو',goal:studioDraft.goal,body:studioDraft.raw||studioDraft.topic,draft:{...studioDraft},updated:new Intl.DateTimeFormat('fa-IR-u-nu-latn',{day:'numeric',month:'long'}).format(new Date())});persist()}else addLibrary({title:studioDraft.topic,type:'سناریو',goal:studioDraft.goal,body:studioDraft.mode==='have'?studioDraft.raw:studioDraft.topic,draft:{...studioDraft}});notify('سناریو در کتابخانه ذخیره شد')}break;case 'calendar-draft':if(studioDraft){const content={title:studioDraft.topic,type:'سناریو',goal:studioDraft.goal,body:studioDraft.raw||studioDraft.topic},savedId=addLibrary(content);scheduleItem({...content,id:savedId});location.hash='#/app/calendar';refresh();notify('سناریو در کتابخانه و تقویم ذخیره شد')}break;case 'plan-content':{const item=product.library.find(v=>v.id===id);if(!item)return;scheduleItem(item);location.hash='#/app/calendar';refresh();notify('محتوا به برنامه هفته اضافه شد');break}case 'remove-content':if(window.confirm('این محتوا و برنامه‌های مرتبط با آن از داده‌های محلی حذف شوند؟')){const removedEntry=product.library.find(entry=>entry.id===id),removedIdea=removedEntry?.sourceIdea??sampleIdeas.findIndex(v=>v.title===removedEntry?.title);product.library=product.library.filter(v=>v.id!==id);if(removedIdea>=0)product.savedIdeas=product.savedIdeas.filter(v=>v!==removedIdea);product.calendar=product.calendar.filter(v=>v.contentId!==id);persist();refresh();notify('محتوا حذف شد')}break;case 'remove-plan':product.calendar=product.calendar.filter(v=>v.id!==id);persist();refresh();notify('محتوا از برنامه حذف شد');break;case 'select-day':selectedDay=button.dataset.date;refresh();document.getElementById('calendar-item')?.focus();break;case 'suggest-week':{const days=weekDays();if(product.calendar.some(v=>days.some(d=>localDay(d)===v.date))&&!window.confirm('برنامه فعلی این هفته حفظ می‌شود و 3 پیشنهاد نمونه به آن اضافه خواهد شد. ادامه می‌دهید؟'))return;[0,1,4].forEach((index,j)=>scheduleItem({id:`idea-${index}`,title:sampleIdeas[index].title,goal:sampleIdeas[index].goal,type:sampleIdeas[index].type},localDay(days[[0,2,4][j]])));refresh();notify('3 پیشنهاد نمونه به هفته اضافه شد');break}case 'export':{const blob=new Blob([JSON.stringify(product,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='brandyar-data.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('فایل داده‌های محلی آماده شد');break}case 'reset-account':if(window.confirm('تمام اطلاعات نمایشی ذخیره‌شده در این مرورگر حذف شود؟')){localStorage.removeItem('brandyar-product-v1');localStorage.removeItem('brandyar-saved-ideas');product={...defaults,mode:'new',brand:Object.fromEntries(Object.keys(sampleBrand).map(k=>[k,''])),tasks:{},savedIdeas:[],library:[],calendar:[]};location.hash='#/app';refresh();notify('داده‌های محلی حذف شدند')}break}});
(() => {
  const types = ['User','BrandProfile','AudienceProfile','ValueProposition','BrandVoice','ContentPillar','ProductOrService','EvidenceItem','ContentIdea','WeeklyPlan','ContentPiece','ContentBrief','SourceMaterial','AngleOption','DraftVersion','ReviewItem','LearningLog'];
  const states = ['ایده','در حال ساخت','نیازمند بازبینی','آمادهٔ انتشار','منتشرشده'];
  const sources = {user_input:'ثبت مستقیم شما',assessment:'پاسخ ارزیابی',consultation_summary:'خلاصهٔ گفتگو',assistant_suggestion:'پیشنهاد دستیار',system_default:'پیش‌فرض سیستم'};
  const storeKey = 'brandyar-workspace-v1';
  let saved;
  try { saved = JSON.parse(localStorage.getItem(storeKey)); } catch {}
  const data = Object.fromEntries(types.map(type => [type, Array.isArray(saved?.[type]) ? saved[type] : []]));
  let consent = saved?.consent === true;
  let activePiece = null;
  let ideaLimit = 4;
  const make = (type, fields, source = 'user_input') => {
    const now = new Date().toISOString();
    const record = {id: Array.from(crypto.getRandomValues(new Uint32Array(4)), n => n.toString(16).padStart(8,'0')).join(''), createdAt: now, updatedAt: now, source, status:'draft', ...fields};
    data[type].push(record); save(); return record;
  };
  const update = (record, fields) => {Object.assign(record, fields, {updatedAt: new Date().toISOString()}); save();};
  const save = () => {if (consent) localStorage.setItem(storeKey, JSON.stringify({...data, consent}));};
  const one = type => data[type].find(item => item.status !== 'archived');
  const visible = type => data[type].filter(item => item.status !== 'archived');
  const text = value => esc(value || '');
  const provenance = record => `<small class="db-source">${sources[record.source] || sources.user_input} · ${record.status === 'confirmed' ? 'تأییدشده' : record.status === 'needs_review' ? 'نیازمند بازبینی' : 'پیش‌نویس'}</small>`;
  const field = (name, label, value = '', required = false, area = false) => `<label class="db-field">${label}${area ? `<textarea name="${name}" maxlength="1500" rows="3" ${required?'required':''}>${text(value)}</textarea>` : `<input name="${name}" maxlength="220" value="${text(value)}" ${required?'required':''}>`}</label>`;
  const select = (name, label, choices, value) => `<label class="db-field">${label}<select name="${name}">${choices.map(choice => `<option ${choice===value?'selected':''}>${choice}</option>`).join('')}</select></label>`;
  const controls = (type, record) => `<div class="db-actions"><button type="button" data-db="confirm" data-type="${type}" data-id="${record.id}">تأیید</button><button type="button" data-db="archive" data-type="${type}" data-id="${record.id}">آرشیو</button><button type="button" data-db="delete" data-type="${type}" data-id="${record.id}">حذف</button></div>`;
  const card = (title, content, extra = '') => `<section class="db-card"><h2>${title}</h2>${content}${extra}</section>`;
  const notice = '<p class="db-notice">پیش‌نمایش دستی است؛ اطلاعات فقط در همین صفحه می‌ماند، مگر ذخیره در این مرورگر را فعال کنید. هیچ داده‌ای به سرور یا هوش مصنوعی ارسال نمی‌شود.</p>';
  const empty = (message, path, label) => `<p class="db-empty">${message}</p><a class="btn btn-outline btn-sm" href="#/app/${path}">${label}</a>`;
  const title = (name, description) => `${appTitle(name, description)}${notice}`;
  const currentWeek = () => {const day = new Date(), saturday = new Date(day); saturday.setDate(day.getDate() - (day.getDay() + 1) % 7); return saturday.toISOString().slice(0,10)};
  const plan = () => visible('WeeklyPlan').find(item => item.week === currentWeek());
  const pieces = () => visible('ContentPiece');
  const pieceLink = piece => `<a class="inline-link" href="#/app/studio?piece=${piece.id}">ورود به استودیو</a>`;
  const pieceRow = piece => `<div class="db-row"><div><strong>${text(piece.title)}</strong><small>${text(piece.state)} · ${text(piece.goal || 'هدف ثبت نشده')}</small>${provenance(piece)}</div><div class="db-actions">${pieceLink(piece)}<button type="button" data-db="delete" data-type="ContentPiece" data-id="${piece.id}">حذف</button></div></div>`;
  const today = () => {
    const brand = one('BrandProfile'), weekly = plan(), next = pieces().find(piece => piece.state !== 'منتشرشده' && piece.state !== 'آمادهٔ انتشار'), recent = visible('LearningLog').at(-1);
    return `${title('امروز', `سلام${brand?.name ? `، ${text(brand.name)}` : ''}؛ امروز روی یک قدم روشن تمرکز کن.`)}<div class="db-grid">${card('قدم بعدی', next ? `<p>${text(next.title)} · ${text(next.state)}</p>${pieceLink(next)}` : brand ? `<p>یک موضوع کوچک برای این هفته انتخاب کن.</p><a class="btn btn-dark btn-sm" href="#/app/plan">برنامهٔ هفته را بچین</a>` : empty('برای شروع، چند خط دربارهٔ برند خودت بنویس.','brand','ساخت برند من'))}${card('تعهد این هفته', weekly ? `<p>${weekly.capacity} محتوا در هفته · هدف: ${text(weekly.goal)}</p>${pieces().slice(0,weekly.capacity).map(pieceRow).join('') || '<p>هنوز محتوایی برای این هفته ثبت نکرده‌ای.</p>'}` : empty('هنوز برنامه‌ای نساخته‌ای. با یک محتوا هم می‌شود شروع کرد.','plan','ساخت برنامه'))}${card('برند من', brand ? `<p>${text(brand.field)}</p><p>${text(one('AudienceProfile')?.description || 'مخاطب اولویت‌دار هنوز ثبت نشده است.')}</p><a class="inline-link" href="#/app/brand">ویرایش برند</a>` : empty('هنوز مشخص نکرده‌ای مخاطب اولویت‌دارت کیست.','brand','تکمیل برند'))}${card('آخرین یادگیری', recent ? `<p>${text(recent.reaction)}</p><p>${text(recent.next)}</p><a class="inline-link" href="#/app/learning">مرور یادگیری‌ها</a>` : empty('بعد از انتشار اولین محتوا، تجربه‌ات را اینجا ثبت کن.','learning','ثبت یادگیری'))}</div>`;
  };
  const brand = () => `${title('برند من','شناخت مخاطب، پیام، تجربه و لحن؛ همه قابل اصلاح با نظر خودت.')}<div class="db-grid">${card('هویت و مخاطب اولویت‌دار', `<form data-db-form="identity">${field('name','نام یا عنوان برند',one('BrandProfile')?.name,true)}${field('field','حوزهٔ تخصص',one('BrandProfile')?.field,true)}${field('audience','مخاطب اولویت‌دار و مسئلهٔ او',one('AudienceProfile')?.description,true,true)}${field('value','چه کمکی می‌کنی و چرا به تو اعتماد کنند؟',one('ValueProposition')?.description,false,true)}<button class="btn btn-dark btn-sm">ذخیرهٔ هویت</button></form>${['BrandProfile','AudienceProfile','ValueProposition'].map(type => one(type) ? provenance(one(type)) : '').join('')}`)}${card('تجربه و شاهد واقعی', `<form data-db-form="evidence">${field('detail','یک تجربه، نمونه یا شاهد واقعی', '',true,true)}<button class="btn btn-outline btn-sm">افزودن تجربه</button></form>${visible('EvidenceItem').map(item => `<div class="db-row"><div>${text(item.detail)}${provenance(item)}</div>${controls('EvidenceItem',item)}</div>`).join('') || '<p class="db-empty">هنوز تجربه‌ای ثبت نکرده‌ای؛ لازم نیست ادعایی بسازی.</p>'}`)}${card('محصول یا خدمت', `<form data-db-form="offer">${select('kind','وضعیت', ['فعلاً محصول یا خدمت ندارم','محصول یا خدمت دارم'],one('ProductOrService')?.kind)}${field('description','توضیح محصول یا خدمت (در صورت وجود)',one('ProductOrService')?.description)}<button class="btn btn-outline btn-sm">ذخیرهٔ وضعیت</button></form><p>${one('ProductOrService')?.kind === 'محصول یا خدمت دارم' ? text(one('ProductOrService').description || 'توضیح خدمت را اضافه کن.') : 'فعلاً تمرکز ما روی ساخت اعتماد، وضوح پیام و شناخت مخاطب است.'}</p>`)}${card('ستون‌های محتوا', `<p>۳ تا ۵ موضوع تکرارشونده برای محتوا انتخاب کن.</p><form data-db-form="pillar">${field('title','موضوع ستون', '',true)}<button class="btn btn-outline btn-sm" ${visible('ContentPillar').length>=5?'disabled':''}>افزودن ستون</button></form>${visible('ContentPillar').map(item => `<div class="db-row">${text(item.title)} ${provenance(item)} ${controls('ContentPillar',item)}</div>`).join('')}`)}${card('لحن و قواعد نوشتن', `<form data-db-form="voice">${field('tone','لحن مطلوب',one('BrandVoice')?.tone)}${field('example','یک جملهٔ واقعی به لحن خودت',one('BrandVoice')?.example,false,true)}${field('use','واژه‌هایی که به کار می‌برم',one('BrandVoice')?.use)}${field('avoid','واژه‌هایی که نمی‌خواهم',one('BrandVoice')?.avoid)}<button class="btn btn-outline btn-sm">ذخیرهٔ لحن</button></form>${one('BrandVoice') ? provenance(one('BrandVoice')) : '<p class="db-empty">یک جمله از نوشتهٔ خودت کمک می‌کند لحن واقعی‌ات حفظ شود.</p>'}`)}</div>`;
  const ideaSources = ['سؤال واقعی مخاطب','تجربهٔ شخصی','اشتباه یا سوءبرداشت رایج','نکته‌ای از آموزش','نمونه‌کار با اجازه','پرسشی که خودم داشتم'];
  const program = () => {const weekly = plan();return `${title('برنامه','هدف و ظرفیت واقعی‌ات را ثبت کن؛ انتشار خودکار وجود ندارد.')}<div class="db-grid">${card('هدف و ظرفیت این هفته',`<form data-db-form="week">${field('goal','هدف فعلی',weekly?.goal,true)}${select('capacity','تعهد هفتگی', ['۱','۲','۳'],weekly?.capacity)}<button class="btn btn-dark btn-sm">ذخیرهٔ برنامه</button></form>${weekly ? provenance(weekly) : ''}`)}${card('برنامهٔ محتوا', `${pieces().map(piece => `<div class="db-row"><div><strong>${text(piece.title)}</strong><small>${text(piece.state)}</small></div><div class="db-actions"><label>وضعیت<select data-db-state="${piece.id}">${states.map(state=>`<option ${piece.state===state?'selected':''}>${state}</option>`).join('')}</select></label>${pieceLink(piece)}<button type="button" data-db="delete" data-type="ContentPiece" data-id="${piece.id}">حذف</button></div></div>`).join('') || '<p class="db-empty">هنوز محتوایی در برنامه نیست.</p>'}<form data-db-form="piece">${field('title','عنوان محتوا','',true)}<button class="btn btn-outline btn-sm" ${weekly && pieces().filter(p=>p.week===currentWeek()).length>=Number(weekly.capacity.replace(/[۱۲۳]/g,c=>({'۱':1,'۲':2,'۳':3}[c])))?'disabled':''}>افزودن محتوا</button></form>`)}${card('بانک ایده', `<p>منبع ایده را خودت انتخاب کن؛ پیشنهادها از پیج استخراج نشده‌اند.</p><form data-db-form="idea">${field('title','ایدهٔ خودت','',true)}${select('origin','منبع ایده',ideaSources)}<button class="btn btn-outline btn-sm">ثبت ایده</button></form>${visible('ContentIdea').slice(0,ideaLimit).map(item=>`<div class="db-row"><div><strong>${text(item.title)}</strong><small>${text(item.origin)}</small>${provenance(item)}</div><div class="db-actions"><button type="button" data-db="idea-to-piece" data-id="${item.id}">افزودن به برنامه</button>${controls('ContentIdea',item)}</div></div>`).join('') || '<p class="db-empty">اولین ایده را از یک سؤال یا تجربهٔ واقعی ثبت کن.</p>'}${visible('ContentIdea').length>ideaLimit?'<button type="button" data-db="more-ideas">دیدن ایده‌های بیشتر</button>':''}`)}</div>`};
  const studio = () => {
    const query = new URLSearchParams(location.hash.split('?')[1]||'');
    const selected = pieces().find(piece => piece.id === (query.get('piece') || activePiece)) || pieces()[0];
    if (selected) activePiece = selected.id;
    const brief = visible('ContentBrief').find(item=>item.pieceId===selected?.id), material = visible('SourceMaterial').find(item=>item.pieceId===selected?.id), angles = visible('AngleOption').filter(item=>item.pieceId===selected?.id), draft = visible('DraftVersion').find(item=>item.pieceId===selected?.id), reviews = visible('ReviewItem').filter(item=>item.pieceId===selected?.id);
    return `${title('استودیو','هفت قدم از بریف تا آماده‌سازی؛ تصمیم، صدا و تأیید نهایی با توست.')}<div class="db-card"><label class="db-field">محتوای در حال ساخت<select id="db-piece-select">${pieces().map(piece=>`<option value="${piece.id}" ${piece===selected?'selected':''}>${text(piece.title)}</option>`).join('')}</select></label>${selected?'':'<p class="db-empty">ابتدا در برنامه یک محتوا ثبت کن.</p><a href="#/app/plan" class="btn btn-outline btn-sm">رفتن به برنامه</a>'}</div>${selected ? `<div class="db-flow">${card('۱. بریف',`<form data-db-form="brief">${field('goal','هدف این محتوا',brief?.goal,true)}${field('audience','برای چه کسی؟',brief?.audience,true)}${field('message','پیام اصلی',brief?.message,true,true)}<button class="btn btn-dark btn-sm">ذخیرهٔ بریف</button></form>`)}${card('۲. مادهٔ اولیه',`<p>دستیار می‌تواند ساختار بدهد، اما تجربه و نگاه واقعی توست که محتوا را متمایز می‌کند.</p><form data-db-form="material">${field('experience','یک تجربه، مشاهده یا مثال واقعی',material?.experience,true,true)}<button class="btn btn-outline btn-sm">ذخیرهٔ تجربه</button></form>`)}${card('۳. زاویهٔ روایت',brief && material ? `${['تجربهٔ شخصی','پرسش مخاطب','سوءبرداشت رایج'].map((angle,i)=>`<div class="db-row"><div><strong>${angle}</strong><p>${['برای نشان‌دادن روش واقعی تو','برای شروع از مسئلهٔ مخاطب','برای روشن‌کردن یک برداشت نادرست'][i]}</p><small>شروع پیشنهادیِ ساختاری: ${text(brief.message)} — ${angle}</small></div><button type="button" data-db="angle" data-value="${angle}">${angles.find(a=>a.title===angle)?.selected?'انتخاب‌شده':'انتخاب'}</button></div>`).join('')}`:'<p class="db-empty">برای دیدن زاویه‌های ساختاری، بریف و تجربهٔ واقعی را کامل کن.</p>')}${card('۴. ساختار',`<p>بخش‌ها را اضافه کن، جابه‌جا کن یا حذف کن. ترتیب نهایی با توست.</p><form data-db-form="block">${field('body','متن بخش', '',true,true)}<button class="btn btn-outline btn-sm">افزودن بخش</button></form>${(draft?.blocks||[]).map((block,i)=>`<div class="db-row"><p>${text(block)}</p><div class="db-actions"><button type="button" data-db="block-up" data-index="${i}" ${i===0?'disabled':''}>بالاتر</button><button type="button" data-db="block-down" data-index="${i}" ${i===(draft.blocks.length-1)?'disabled':''}>پایین‌تر</button><button type="button" data-db="block-remove" data-index="${i}">حذف</button></div></div>`).join('')}`)}${card('۵. پیش‌نویس',`<form data-db-form="draft">${field('body','متن قابل ویرایش تو',draft?.body,false,true)}<button class="btn btn-dark btn-sm">ذخیرهٔ پیش‌نویس</button></form><p class="db-notice">برای دریافت پیشنهادهای هوشمند، ابتدا بریف را کامل کن. بازنویسی هوشمند هنوز متصل نیست.</p><div class="db-actions">${['بازنویسی','کوتاه‌سازی','شفاف‌سازی','تغییر لحن','پیشنهاد CTA'].map(action=>`<button type="button" disabled title="هوش مصنوعی هنوز متصل نیست">${action} · به‌زودی</button>`).join('')}</div>`)}${card('۶. بازبینی حرفه‌ای',`<p>این فهرست به‌جای امتیاز یا وعدهٔ بازدید، به بازبینی خودت کمک می‌کند.</p>${['وضوح پیام','مثال یا تجربهٔ واقعی','شفافیت ادعا','دعوت به اقدام'].map((label,i)=>{const record=reviews.find(item=>item.label===label);return `<label class="db-field">${label}<select data-db-review="${label}">${['نیازمند بررسی','آماده','نیازمند افزودن تجربه یا مثال','نیازمند شفاف‌سازی ادعا','نیازمند انتخاب CTA'].map(state=>`<option ${state===(record?.result||['نیازمند بررسی','نیازمند افزودن تجربه یا مثال','نیازمند شفاف‌سازی ادعا','نیازمند انتخاب CTA'][i])?'selected':''}>${state}</option>`).join('')}</select></label>`}).join('')}`)}${card('۷. آماده‌سازی برای انتشار',`<p>هیچ محتوایی از اینجا به اینستاگرام فرستاده نمی‌شود؛ ثبت وضعیت دستی است.</p><div class="db-actions">${['آمادهٔ انتشار','منتشرشده','بازگشت به برنامه','آرشیو'].map(state=>`<button type="button" data-db="finish" data-value="${state}">${state}</button>`).join('')}</div>`)}</div>`:''}`;
  };
  const learning = () => `${title('یادگیری','پس از انتشار، واکنش‌ها را خودت ثبت و برای هفتهٔ بعد مرور کن.')}<div class="db-grid">${card('ثبت تجربهٔ انتشار',`<form data-db-form="learning">${field('published','چه چیزی منتشر کردی؟','',true)}${field('reaction','کدام واکنش توجهت را جلب کرد؟','',true,true)}${field('surprise','چه چیزی برخلاف انتظار بود؟','',false,true)}${select('approached','به هدف نزدیک شد؟',['مطمئن نیستم','بله، تا حدی','نه هنوز'])}${field('next','دفعهٔ بعد چه چیزی را تغییر می‌دهی؟','',false,true)}<button class="btn btn-dark btn-sm">ثبت یادگیری</button></form>`)}${card('مرور هفتگی',visible('LearningLog').length ? `${visible('LearningLog').slice(-5).reverse().map(item=>`<div class="db-row"><div><strong>${text(item.published)}</strong><p>${text(item.reaction)}</p><small>غافلگیری: ${text(item.surprise || 'ثبت نشده')} · نزدیک به هدف: ${text(item.approached)}</small><p>تغییر بعدی: ${text(item.next || 'هنوز تصمیم نگرفته‌ام')}</p>${provenance(item)}</div>${controls('LearningLog',item)}</div>`).join('')}<p>فرضیهٔ قابل بررسی: ${text(visible('LearningLog').at(-1).next || 'برای هفتهٔ بعد یک تغییر کوچک در شیوهٔ بیان امتحان کن.')} این پیشنهاد بر اساس یادداشت خودت است، نه تحلیل خودکار.</p>`: '<p class="db-empty">بعد از انتشار اولین محتوا، تجربه‌ات را اینجا ثبت کن.</p>')}</div>`;
  for (const key of Object.keys(appPages)) delete appPages[key];
  Object.assign(appPages,{app:today,brand,plan:program,studio,learning});
  function render() {if(!location.hash.startsWith('#/app')) return; route(); document.title = `${({app:'امروز',brand:'برند من',plan:'برنامه',studio:'استودیو',learning:'یادگیری'})[location.hash.split(/[/?]/)[2]||'app']||'داشبورد'} | برندیار`}
  const upsert = (type, values, predicate = () => true) => {const current=visible(type).find(predicate); if(current) update(current,values); else make(type,values);};
  document.addEventListener('submit', event => {
    const form=event.target.closest('[data-db-form]'); if(!form)return;
    event.preventDefault(); const values=Object.fromEntries(new FormData(form)); const kind=form.dataset.dbForm;
    if(kind==='identity'){upsert('BrandProfile',{name:values.name,field:values.field});upsert('AudienceProfile',{description:values.audience});upsert('ValueProposition',{description:values.value});}
    if(kind==='evidence') make('EvidenceItem',{detail:values.detail});
    if(kind==='offer') upsert('ProductOrService',values);
    if(kind==='pillar'&&visible('ContentPillar').length<5) make('ContentPillar',values);
    if(kind==='voice') upsert('BrandVoice',values);
    if(kind==='week') upsert('WeeklyPlan',{...values,week:currentWeek()},item=>item.week===currentWeek());
    if(kind==='piece') {const week=plan(); if(week&&pieces().filter(p=>p.week===currentWeek()).length>=Number(week.capacity.replace(/[۱۲۳]/g,c=>({'۱':1,'۲':2,'۳':3}[c]))))return;make('ContentPiece',{title:values.title,week:currentWeek(),goal:week?.goal||'',state:'ایده'});}
    if(kind==='idea') make('ContentIdea',values);
    if(kind==='learning') make('LearningLog',values);
    if(['brief','material','block','draft'].includes(kind)){
      const selected=pieces().find(item=>item.id===activePiece); if(!selected)return;
      const target={brief:'ContentBrief',material:'SourceMaterial',block:'DraftVersion',draft:'DraftVersion'}[kind];
      if(kind==='block'){const existing=visible(target).find(item=>item.pieceId===selected.id);upsert(target,{pieceId:selected.id,blocks:[...(existing?.blocks||[]),values.body]},item=>item.pieceId===selected.id)}
      else upsert(target,{...values,pieceId:selected.id},item=>item.pieceId===selected.id);
      if(selected.state==='ایده')update(selected,{state:'در حال ساخت'});
    }
    render(); notify('تغییرات ثبت شد');
  });
  document.addEventListener('change',event=>{
    const target=event.target;
    if(target.id==='db-piece-select'){activePiece=target.value;location.hash=`#/app/studio?piece=${activePiece}`;render()}
    if(target.dataset.dbState){const item=pieces().find(p=>p.id===target.dataset.dbState);if(item){update(item,{state:target.value});render()}}
    if(target.dataset.dbReview){const selected=pieces().find(p=>p.id===activePiece);if(selected)upsert('ReviewItem',{pieceId:selected.id,label:target.dataset.dbReview,result:target.value},item=>item.pieceId===selected.id&&item.label===target.dataset.dbReview)}
  });
  document.addEventListener('click',event=>{
    const button=event.target.closest('[data-db]');if(!button)return;
    const action=button.dataset.db,id=button.dataset.id,type=button.dataset.type,record=types.includes(type)?data[type].find(item=>item.id===id):null;
    const selected=pieces().find(piece=>piece.id===activePiece);
    if(action==='confirm'&&record)update(record,{status:'confirmed'});
    if(action==='archive'&&record)update(record,{status:'archived'});
    if(action==='delete'&&record&&confirm('این مورد حذف شود؟')){data[type].splice(data[type].indexOf(record),1);save()}
    if(action==='more-ideas')ideaLimit+=4;
    if(action==='idea-to-piece'){const idea=visible('ContentIdea').find(item=>item.id===id);if(idea){make('ContentPiece',{title:idea.title,week:currentWeek(),goal:plan()?.goal||'',state:'ایده'});location.hash='#/app/plan'}}
    if(action==='angle'&&selected){visible('AngleOption').filter(item=>item.pieceId===selected.id).forEach(item=>update(item,{selected:false}));upsert('AngleOption',{pieceId:selected.id,title:button.dataset.value,selected:true},item=>item.pieceId===selected.id&&item.title===button.dataset.value)}
    if(action.startsWith('block-')&&selected){const draft=visible('DraftVersion').find(item=>item.pieceId===selected.id),blocks=[...(draft?.blocks||[])],index=Number(button.dataset.index);if(action==='block-remove')blocks.splice(index,1);else {const other=index+(action==='block-up'?-1:1);if(other<0||other>=blocks.length)return;[blocks[index],blocks[other]]=[blocks[other],blocks[index]]}update(draft,{blocks})}
    if(action==='finish'&&selected){const state=button.dataset.value;if(state==='آرشیو')update(selected,{status:'archived'});else if(state==='بازگشت به برنامه')location.hash='#/app/plan';else update(selected,{state})}
    render();
  });
  document.querySelector('.app-top').insertAdjacentHTML('beforeend',`<label class="db-consent"><input id="db-consent" type="checkbox" ${consent?'checked':''}> ذخیره در این مرورگر</label><button type="button" id="db-menu" aria-expanded="false" aria-controls="db-mobile-menu">منو</button><nav id="db-mobile-menu" hidden aria-label="منوی داشبورد"><a href="#/app">امروز</a><a href="#/app/brand">برند من</a><a href="#/app/plan">برنامه</a><a href="#/app/studio">استودیو</a><a href="#/app/learning">یادگیری</a><a href="#/">بازگشت به سایت</a></nav>`);
  document.getElementById('db-consent').addEventListener('change',event=>{consent=event.target.checked;if(consent)save();else localStorage.removeItem(storeKey);notify(consent?'ذخیره در مرورگر فعال شد':'دادهٔ ذخیره‌شده در مرورگر پاک شد')});
  document.getElementById('db-menu').addEventListener('click',()=>{const menu=document.getElementById('db-mobile-menu'),open=menu.hidden;menu.hidden=!open;document.getElementById('db-menu').setAttribute('aria-expanded',String(open))});
  document.getElementById('db-mobile-menu').addEventListener('click',event=>{if(event.target.closest('a')){document.getElementById('db-mobile-menu').hidden=true;document.getElementById('db-menu').setAttribute('aria-expanded','false')}});
  window.addEventListener('hashchange',render);
  render();
})();
let byDialogTrigger;
document.addEventListener('click', event => {
  const sampleButton = event.target.closest('[data-by-sample]');
  if (sampleButton) {
    const sample = landingSamples[Number(sampleButton.dataset.bySample)];
    if (!sample) return;
    byDialogTrigger = sampleButton;
    const dialog = document.getElementById('by-sample-dialog');
    document.getElementById('by-sample-title').textContent = sample.title;
    document.getElementById('by-sample-detail').innerHTML = `<div class="by-modal-sample"><img src="/logo.jpg" alt="لوگوی برندیار" width="64" height="64"><h3>${sample.label}</h3><p>${sample.body}</p></div>`;
    dialog.showModal();
  }
  if (event.target.closest('#by-sample-close')) document.getElementById('by-sample-dialog').close();
  if (event.target.closest('#by-kit-replay')) {
    const kit = document.querySelector('.by-kit');
    kit.getAnimations({subtree:true}).forEach(animation => animation.cancel());
    if (!window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      kit.querySelectorAll('.by-kit-grid > div').forEach((item,index) => item.animate([{opacity:.7,transform:`translateY(${index%2?12:-12}px) rotate(${index%2?2:-2}deg)`},{opacity:1,transform:'none'}],{duration:550,easing:'ease-out'}));
    }
  }
});
document.addEventListener('close', event => {if (event.target.id === 'by-sample-dialog') byDialogTrigger?.focus();}, true);
function updateLandingPreview(form) {
  const values = new FormData(form), canvas = document.getElementById('by-demo-canvas');
  if (!canvas) return;
  canvas.dataset.palette = values.get('palette');
  canvas.dataset.font = values.get('font');
  canvas.dataset.layout = values.get('layout');
  document.getElementById('by-demo-copy').textContent = values.get('voice') === 'formal' ? 'یک پیام مشخص انتخاب کنید؛ سپس محتوایی متناسب با هویت و مخاطب خود بنویسید.' : 'از یک پیام روشن شروع کن؛ قدم بعدی را با صدای خودت بنویس.';
  document.getElementById('by-preview-status').textContent = 'پیش‌نمایش به‌روز شد؛ تغییری ذخیره یا ارسال نشده است.';
}
document.addEventListener('change', event => {const form = event.target.closest('#by-preview-controls');if(form) updateLandingPreview(form);});
document.addEventListener('reset', event => {if(event.target.id === 'by-preview-controls') requestAnimationFrame(() => updateLandingPreview(event.target));});
document.addEventListener('submit', event => {if(event.target.id === 'by-preview-controls') event.preventDefault();});

document.addEventListener('click', event => {
  const link = event.target.closest('[data-by-jump]');
  if (!link) return;
  event.preventDefault();
  if (!['', '#/', '#'].includes(location.hash)) { location.hash = '#/'; route(); }
  closeSiteMenu();
  requestAnimationFrame(() => {const section = document.getElementById(link.dataset.byJump); if(section){section.setAttribute('tabindex','-1');section.focus({preventScroll:true});section.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
});
